var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.name!="Garden_Moves" || UnityEditor.EditorApplication.isPlayingOrWillChangePlaymode)throw new System.InvalidOperationException("Open Garden_Moves outside Play mode.");
const string folder="Assets/Materials/GardenPastel/Gronny";if(!UnityEditor.AssetDatabase.IsValidFolder(folder))UnityEditor.AssetDatabase.CreateFolder("Assets/Materials/GardenPastel","Gronny");
var changes=new System.Collections.Generic.List<object>();
foreach(var renderer in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.SkinnedMeshRenderer>(true))){var materials=renderer.sharedMaterials;bool changed=false;for(int i=0;i<materials.Length;i++){var source=materials[i];if(source==null || source.shader.name!="VRM10/Universal Render Pipeline/MToon10" || !source.name.Contains("CLOTH"))continue;var tint=source.GetColor("_Color");if(UnityEngine.Mathf.Max(tint.r,tint.g,tint.b)-UnityEngine.Mathf.Min(tint.r,tint.g,tint.b)<0.07f)continue;
UnityEditor.AssetDatabase.TryGetGUIDAndLocalFileIdentifier(source,out string guid,out long id);string path=folder+"/"+guid+"_"+id+".mat";var target=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>(path);if(target==null){target=new UnityEngine.Material(source);UnityEditor.AssetDatabase.CreateAsset(target,path);}target.name=source.name.Replace(" (Instance)","")+" Soft Shadows";float grey=tint.r*0.2126f+tint.g*0.7152f+tint.b*0.0722f;var shade=UnityEngine.Color.Lerp(tint,new UnityEngine.Color(grey,grey,grey,tint.a),0.12f)*0.85f;shade.a=tint.a;target.SetColor("_ShadeColor",shade);UnityEditor.EditorUtility.SetDirty(target);materials[i]=target;changed=true;changes.Add(new{material=target.name,path,lit=tint.ToString(),oldShade=source.GetColor("_ShadeColor").ToString(),shade=shade.ToString(),texturePreserved=target.GetTexture("_MainTex")==source.GetTexture("_MainTex"),shader=target.shader.name});}
if(!changed)continue;UnityEditor.Undo.RecordObject(renderer,"Soften Gronny clothing shadows");renderer.sharedMaterials=materials;UnityEditor.PrefabUtility.RecordPrefabInstancePropertyModifications(renderer);}
UnityEditor.AssetDatabase.SaveAssets();UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);System.IO.File.WriteAllText("Docs/Validation/GronnyClothingShadows.json",Newtonsoft.Json.JsonConvert.SerializeObject(changes,Newtonsoft.Json.Formatting.Indented));return new{changed=changes.Count,saved=!scene.isDirty,materials=changes};
